import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import BaseLayout from "../../../layouts/BaseLayout";
import ProfileCard from "./Components/ProfileCard";
import ProfileControll from "./Components/ProfileControll";
import InvoiceModal from "./Components/Modal/InvoiceModal";
import axios from "axios";
import Loader from "./Components/Loader"; // Import the Loader

const Profile = () => {
  const { patientId } = useParams(); // Get the patient ID from the route
  const [patientData, setPatientData] = useState(null);
  const [isLoadingProfileCard, setIsLoadingProfileCard] = useState(true); // For ProfileCard loading
  const [isLoadingProfileControll, setIsLoadingProfileControll] =
    useState(true); // For ProfileControll loading
  const [showModal, setShowModal] = useState(false);

  const showinvoice = () => setShowModal(true);
  const closeModal = () => setShowModal(false);

  useEffect(() => {
    const fetchPatientData = async () => {
      try {
        const response = await axios.get(
          `https://consultant-backend-jiwv.onrender.com/patient/${patientId}`
        );
        setPatientData(response.data.data);
        setIsLoadingProfileCard(false); // Stop loader for ProfileCard
        setIsLoadingProfileControll(false); // Stop loader for ProfileControll
      } catch (error) {
        console.error("Error fetching patient data:", error);
      }
    };

    fetchPatientData();
  }, [patientId]);

  return (
    <BaseLayout>
      <div className="mx-5 flex justify-between">
        <h3 className="py-2 font-bold text-gray-700 text-lg">
          Patient Profile
        </h3>
      </div>

      <div className="flex flex-row justify-center gap-10 mt-5 mx-5">
        {/* Loader for ProfileCard */}
        {isLoadingProfileCard ? (
          <Loader /> // Show loader while waiting for ProfileCard data
        ) : (
          patientData && <ProfileCard patientData={patientData} />
        )}

        {/* Loader for ProfileControll */}
        {isLoadingProfileControll ? (
          <Loader /> // Show loader while waiting for ProfileControll
        ) : (
          <ProfileControll showinvoice={showinvoice} />
        )}
      </div>
      <InvoiceModal show={showModal} onClose={closeModal} />
    </BaseLayout>
  );
};

export default Profile;
